<script module lang="ts">
/**
 * A date *field* with segmented entry and a calendar popup (`design/components/date-picker.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/date-picker.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/popover'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  agentDate,
  agentDateTime,
  agentMember,
  anchorProps,
  attributes,
  calendarDateOf,
  dateFieldDraft,
  dateFieldValue,
  dateOutOfBounds,
  eraseSegment,
  fieldSegments,
  joinSlot,
  normalizeProps,
  stepSegment,
  syncTriggerAnchor,
  typeIntoSegment,
  useDirection,
  useMediaQuery,
  watchEffect,
  type CalendarDateTime,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/controls/date-picker.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import triggerAnchor from '@polymorph/recipes/overlays/trigger-anchor.module.css'
import Button from './Button.svelte'
import Calendar from './Calendar.svelte'
import type { CalendarDate, CalendarMessages } from './Calendar.svelte'

export type DatePickerMessages = CalendarMessages & {
  showCalendar: string
  clear: string
  chooseDate: string
}

export interface DatePickerProps {
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  /**
   * Input's clear button. Clearing returns the segments to their placeholders.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: CalendarDate | null | CalendarDateTime
  disabled?: boolean
  firstDayOfWeek?: 0 | 1 | 2 | 3 | 4 | 5 | 6
  granularity?: 'day' | 'hour' | 'minute'
  id?: string
  invalid?: boolean
  isDateUnavailable?: (date: CalendarDate) => boolean
  /**
   * Orders the segments as well as naming the months.
   */
  locale?: string
  maxValue?: CalendarDate
  /**
   * Defaults to generic English. Localized hosts pass strings from their catalog.
   */
  messages?: DatePickerMessages
  minValue?: CalendarDate
  /**
   * Serializes ISO-8601, at the granularity.
   */
  name?: string
  onChange?: ((value: CalendarDate | null) => void) | ((value: CalendarDateTime | null) => void)
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation),
   * with Calendar unchanged inside it. `'popover'` keeps the popover at every width. There is no
   * always-sheet value (`docs/layout.md`). The segments stay the primary input at every width,
   * and the field itself never becomes a sheet.
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * `CalendarDateTime`: the same package's datetime type, without a time zone, never a JS `Date`
   * (Calendar's law). The value type follows the granularity, and React Aria enforces the match
   * at runtime instead of inventing a midnight time.
   */
  value?: CalendarDate | null | CalendarDateTime
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  clearable = false,
  defaultOpen,
  defaultValue,
  disabled = false,
  firstDayOfWeek,
  granularity = 'day',
  id: idOwn,
  invalid: invalidOwn = false,
  isDateUnavailable,
  locale,
  maxValue,
  messages,
  minValue,
  name,
  onChange,
  presentation = 'auto',
  size = 'md',
  value,
}: DatePickerProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let browserLanguage = $state(undefined as string | undefined)
// svelte-ignore state_referenced_locally
let draft = $state(
  dateFieldDraft(value !== undefined ? value : defaultValue, {
    locale: locale ?? browserLanguage ?? 'en-US',
    parts:
      granularity === 'minute'
        ? (['year', 'month', 'day', 'hour', 'minute'] as const)
        : granularity === 'hour'
          ? (['year', 'month', 'day', 'hour'] as const)
          : (['year', 'month', 'day'] as const),
  }),
)
let typed = $state('')
// svelte-ignore state_referenced_locally
let reported = $state((value !== undefined ? value : defaultValue)?.toString() ?? '')
let anchor = $state<HTMLElement | null>(null)
let field = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
let scrim = $state<HTMLElement | null>(null)
let sheetPanel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const say = $derived(
  messages ?? {
    previousMonth: 'Previous month',
    nextMonth: 'Next month',
    showCalendar: 'Show calendar',
    clear: 'Clear',
    chooseDate: 'Choose a date',
  },
)
const language = $derived(locale ?? browserLanguage ?? 'en-US')
const sheeting = $derived(presentation === 'auto' && phone.current)
const fieldOptions = $derived({
  locale: language,
  parts:
    granularity === 'minute'
      ? (['year', 'month', 'day', 'hour', 'minute'] as const)
      : granularity === 'hour'
        ? (['year', 'month', 'day', 'hour'] as const)
        : (['year', 'month', 'day'] as const),
})
const segments = $derived(fieldSegments(draft, fieldOptions))
const kept = $derived((value !== undefined ? value : defaultValue) ?? null)
const current = $derived(dateFieldValue(draft, fieldOptions, kept))
const fieldInvalid = $derived(
  invalid ||
    dateOutOfBounds(current, { min: minValue, max: maxValue, unavailable: isDateUnavailable }),
)
const showClear = $derived(clearable && current !== null && !disabled)
const commit = $derived((next: ReturnType<typeof dateFieldDraft>): void => {
  draft = next
  const after = dateFieldValue(next, fieldOptions, kept)
  const text = after?.toString() ?? ''
  if (text !== reported) {
    reported = text
    ;(onChange as ((...args: any[]) => unknown) | undefined)?.(after)
  }
})
const clear = $derived((): void => {
  commit({})
  field?.querySelector<HTMLElement>('[data-segment]')?.focus()
})
const segmentName = $derived((type: string): string => {
  try {
    return new Intl.DisplayNames(language, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = $derived((from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const segmentInput = $derived(
  (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
    event.preventDefault()
    if (segment.type === 'literal' || !!disabled) return
    const data = (event as InputEvent).data ?? ''
    for (const key of data) {
      const next = typeIntoSegment(draft, segment.type, typed, key, fieldOptions)
      typed = next.typed
      commit(next.draft)
      if (next.advance) {
        moveSegment(event.currentTarget, 1)
        break
      }
    }
  },
)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen,
      modal: sheeting,
      positioning: { placement: 'bottom-end' as const, offset: { mainAxis: 2 } },
      ids: id === undefined ? undefined : { anchor: id },
      initialFocusEl: () =>
        (sheetPanel ?? panel)?.querySelector<HTMLElement>('[tabindex="0"]') ?? null,
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const choose = $derived((date: CalendarDate | null): void => {
  if (date === null) return
  commit({ ...draft, year: date.year, month: date.month, day: date.day })
  api.setOpen(false)
})
const segmentKeys = $derived(
  (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
    if (segment.type === 'literal') return
    if (event.altKey && event.key === 'ArrowDown') {
      event.preventDefault()
      if (!disabled) api.setOpen(true)
      return
    }
    if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
      event.preventDefault()
      typed = ''
      moveSegment(
        event.currentTarget,
        (event.key === 'ArrowRight') ===
          (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
          ? 1
          : -1,
      )
      return
    }
    if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
    const editable = !disabled
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault()
      typed = ''
      if (editable)
        commit(stepSegment(draft, segment.type, event.key === 'ArrowUp' ? 1 : -1, fieldOptions))
      return
    }
    if (event.key === 'Backspace' || event.key === 'Delete') {
      event.preventDefault()
      typed = ''
      if (!editable) return
      if (draft[segment.type] === undefined) moveSegment(event.currentTarget, -1)
      else commit(eraseSegment(draft, segment.type, fieldOptions))
      return
    }
    if (event.key.length !== 1) return
    event.preventDefault()
    if (editable)
      ((key: string): void => {
        const next = typeIntoSegment(draft, segment.type, typed, key, fieldOptions)
        typed = next.typed
        commit(next.draft)
        if (next.advance) moveSegment(event.currentTarget, 1)
      })(event.key)
  },
)
const present = usePresence(
  () => api.open && !sheeting,
  () => panel,
)
const sheetPresent = usePresence(
  () => api.open && sheeting,
  () => sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(
  () => api.open && sheeting,
  () => scrim,
  'dialog.scrim',
)
const effect1 = () => {
  ;((browserLanguage = globalThis.navigator?.language),
    locale === undefined &&
      (draft = dateFieldDraft(value !== undefined ? value : defaultValue, {
        locale: locale ?? browserLanguage ?? 'en-US',
        parts:
          granularity === 'minute'
            ? (['year', 'month', 'day', 'hour', 'minute'] as const)
            : granularity === 'hour'
              ? (['year', 'month', 'day', 'hour'] as const)
              : (['year', 'month', 'day'] as const),
      })))
}
watchEffect(effect1)
const effect2 = () => {
  syncTriggerAnchor(anchor, api.getTriggerProps(), api.open)
}
watchEffect(effect2, { watch: () => api.open })
const effect3 = () => {
  value !== undefined &&
    (value !== null || current !== null) &&
    ((draft = dateFieldDraft(value, fieldOptions)), (reported = value?.toString() ?? ''))
}
watchEffect(effect3, { watch: () => value, mount: false })
let release4: (() => void) | undefined
const effect4 = () => {
  release4?.()
  const ran = agentMember({
    member: 'DatePicker',
    element: () => field,
    state: () => ({
      value: current?.toString() ?? '',
      open: api.open,
      disabled: disabled,
      invalid: fieldInvalid,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            const bounds = { min: minValue, max: maxValue, unavailable: isDateUnavailable }
            commit(
              dateFieldDraft(
                granularity === 'day'
                  ? agentDate(value, bounds)
                  : agentDateTime(value, bounds, granularity),
                fieldOptions,
              ),
            )
          })(),
      },
      clear: () => commit({}),
      open: () => api.setOpen(true),
      close: () => api.setOpen(false),
    },
    withholds: () => [field, sheetPanel ?? panel],
  })
  release4 = () => {
    ran()
  }
}
watchEffect(effect4)
onDestroy(() => release4?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={field}
    {...attributes(api.getAnchorProps())}
    class={styles.field}
    role="group"
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-disabled={(disabled) ? 'true' : undefined}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(fieldInvalid) ? '' : undefined}
    data-state={api.open ? 'open' : 'closed'}
    data-member="date-picker"
    ><div class={styles.segments} data-size={size}
      >{#each segments as segment, at (`date-${segment.type}-${at}`)
        }{#if segment.type === 'literal'
          }<span class={styles.separator} aria-hidden="true">{segment.text}</span
        >{:else
          }<div
            class={styles.segment}
            role="spinbutton"
            id={`${uid}-date-${segment.type}`}
            aria-label={segmentName(segment.type)}
            aria-labelledby={(ariaLabelledby) ? `${ariaLabelledby} ${uid}-date-${segment.type}` : undefined}
            aria-describedby={ariaDescribedby}
            aria-valuenow={segment.placeholder ? undefined : segment.value}
            aria-valuemin={segment.min}
            aria-valuemax={segment.max}
            aria-valuetext={segment.placeholder ? 'Empty' : segment.text}
            aria-required={(ariaRequired) ? 'true' : undefined}
            aria-disabled={(disabled) ? 'true' : undefined}
            aria-invalid={(fieldInvalid) ? 'true' : undefined}
            contenteditable={(!disabled) ? 'true' : undefined}
            inputmode={segment.type === 'dayPeriod' ? undefined : 'numeric'}
            spellcheck="false"
            tabindex={(disabled ? undefined : '0') as never}
            data-segment={segment.type}
            data-placeholder={(segment.placeholder) ? '' : undefined}
            data-disabled={(disabled) ? '' : undefined}
            onfocus={() => { typed = '' }}
            onkeydown={(event) => { segmentKeys(event, segment) }}
            onbeforeinput={(event) => { segmentInput(event, segment) }}
            >{segment.text
          }</div
        >{/if
      }{/each
    }</div
    >{#if name !== undefined
      }<input
        type="hidden"
        {name}
        value={current?.toString() ?? ''}
        disabled={(disabled) ? true : undefined}
    />{/if
    }{#if showClear
      }<button class={styles.clear} type="button" aria-label={say.clear} onclick={() => { clear() }}
        ><Icon name="clear" {size}
      /></button
    >{/if
    }<span
      bind:this={anchor}
      {...attributes(anchorProps(api.getTriggerProps()))}
      class={triggerAnchor.anchor}
      ><Button
        variant="ghost"
        tone="neutral"
        {size}
        iconOnly={true}
        icon="calendar"
        label={say.showCalendar}
        {disabled}
    /></span
  ></div
  ><Portal
    >{#if present.current
      }<div {...attributes(api.getPositionerProps())}
        ><div
          bind:this={panel}
          {...attributes(api.getContentProps())}
          class={styles.content}
          style:--radix-popover-content-transform-origin={'var(--transform-origin)'}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={say.chooseDate}
          data-member="date-picker"
          ><Calendar
            value={current === null ? null : calendarDateOf(current)}
            {minValue}
            {maxValue}
            {isDateUnavailable}
            locale={language}
            {firstDayOfWeek}
            messages={say}
            aria-label={say.chooseDate}
            onChange={(event) => { choose(event) }}
        /></div
      ></div
    >{/if
    }{#if scrimPresent.current
      }<div bind:this={scrim} class={sheet.scrim} data-state={api.open ? 'open' : 'closed'}></div
    >{/if
    }{#if sheetPresent.current
      }<div class={sheet.positioner}
        ><div
          bind:this={sheetPanel}
          {...attributes(api.getContentProps())}
          class={sheet.panel}
          hidden={undefined}
          aria-labelledby={undefined}
          aria-describedby={undefined}
          aria-label={say.chooseDate}
          aria-modal="true"
          data-presentation="sheet"
          ><div class={styles.sheetBody} data-member="date-picker"
            ><Calendar
              value={current === null ? null : calendarDateOf(current)}
              {minValue}
              {maxValue}
              {isDateUnavailable}
              locale={language}
              {firstDayOfWeek}
              messages={say}
              aria-label={say.chooseDate}
              onChange={(event) => { choose(event) }}
          /></div
        ></div
      ></div
    >{/if
  }</Portal
>{/if
}{@render joined.end?.()}
